let legacyDb;try{legacyDb=JSON.parse(localStorage.getItem(STORE))||emptyDb()}catch{legacyDb=emptyDb()}
let workspaces;try{workspaces=JSON.parse(localStorage.getItem(WORKSPACES_STORE))||[]}catch{workspaces=[]}
if(!workspaces.length){workspaces=[{id:'clan-default',name:legacyDb.clan.name||'Gia phả dòng họ'}];localStorage.setItem(WORKSPACES_STORE,JSON.stringify(workspaces));localStorage.setItem(`${STORE}.clan-default`,JSON.stringify(legacyDb))}
let activeWorkspaceId=localStorage.getItem(ACTIVE_WORKSPACE_STORE)||workspaces[0].id;
if(!workspaces.some(w=>w.id===activeWorkspaceId))activeWorkspaceId=workspaces[0].id;
let db;try{db=JSON.parse(localStorage.getItem(`${STORE}.${activeWorkspaceId}`))||emptyDb()}catch{db=emptyDb()}
let currentView='dashboard',avatarData='';
const save=()=>{try{db.updatedAt=new Date().toISOString();localStorage.setItem(`${STORE}.${activeWorkspaceId}`,JSON.stringify(db));const item=workspaces.find(w=>w.id===activeWorkspaceId);if(item)item.name=db.clan.name||'Gia phả chưa đặt tên';localStorage.setItem(WORKSPACES_STORE,JSON.stringify(workspaces));localStorage.setItem(ACTIVE_WORKSPACE_STORE,activeWorkspaceId);return true}catch(error){console.error('Không thể lưu dữ liệu',error);toast('Không thể lưu: bộ nhớ trình duyệt có thể đã đầy. Hãy sao lưu dữ liệu và giảm ảnh dung lượng lớn.');return false}};
const person=id=>db.persons.find(p=>p.id===id);
const branch=id=>db.branches.find(b=>b.id===id);
const wivesOf=fatherId=>db.persons.filter(x=>x.gender==='female'&&x.membership==='spouse'&&x.spouseOfId===fatherId);
const hasMultipleWives=fatherId=>wivesOf(fatherId).length>=2;
function roomLabel(m){if(!m)return'Chưa xác định Phòng';const titles={'1':'bà Cả','2':'bà Hai','3':'bà Ba','4':'bà Tư','5':'bà Năm'};return `Phòng ${titles[m.marriageOrder]||'người mẹ'} – ${m.name}`}
function generation(id,seen=new Set()){if(!id||seen.has(id))return null;seen.add(id);const p=person(id);if(!p)return null;if(p.generationOverride&&Number(p.generationOverride)>0)return Number(p.generationOverride);if(p.id===db.clan.founderId)return 1;const parent=p.fatherId?person(p.fatherId):null;if(!parent||parent.gender!=='male'||parent.membership==='external')return null;const g=generation(parent.id,seen);return g?g+1:null}
function isMain(p){return p.membership==='lineage'||p.membership==='clan'}
function personDisplayCompare(a,b){const ga=generation(a.id)||999,gb=generation(b.id)||999,ba=branch(a.branchId),bb=branch(b.branchId),oa=Number(ba?.order)||Number(String(ba?.code||'').match(/\d+/)?.[0])||Number(a.branchOrder)||999,ob=Number(bb?.order)||Number(String(bb?.code||'').match(/\d+/)?.[0])||Number(b.branchOrder)||999;return ga-gb||oa-ob||a.name.localeCompare(b.name,'vi')||String(a.code||'').localeCompare(String(b.code||''),'vi')}
function normalizeSearch(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[đĐ]/g,'d').toLowerCase().replace(/[^a-z0-9]+/g,'')}
function duplicateSignature(p){if(!p)return'';const b=branch(p.branchId),parent=branch(b?.parentBranchId),branchPosition=b?[Number(b.order)||'',Number(b.startGeneration)||'',Number(parent?.order)||'',normalizeSearch(parent?.code||parent?.name||b.code||b.name)].join(':'):'none';return [normalizeSearch(p.name),generation(p.id)||'',p.gender||'',p.membership||'',branchPosition,p.fatherId||'',p.motherId||'',normalizeSearch(p.birth),normalizeSearch(p.death)].join('|')}
function childrenOf(id,includeExternal=false){return db.persons.filter(p=>p.fatherId===id||p.motherId===id).filter(p=>includeExternal||p.membership!=='external').sort(personDisplayCompare)}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
function avatar(p,cls='avatar'){return p?.avatar?`<img class="${cls}" src="${p.avatar}" alt="${esc(p.name)}">`:`<span class="${cls}">${initials(p?.name)}</span>`}

function renderDashboard(){
 const main=db.persons.filter(isMain),gens=main.map(p=>generation(p.id)).filter(Boolean),max=Math.max(0,...gens),male=main.filter(p=>p.gender==='male').length,related=db.persons.length-main.length;
 const counts=Array.from({length:max},(_,i)=>main.filter(p=>generation(p.id)===i+1).length);
 $('#dashboard').innerHTML=`<div class="hero"><div><h2>${esc(db.clan.name)}</h2><p>“Uống nước nhớ nguồn · Gìn giữ cội nguồn cho muôn đời sau”</p></div><div class="crest">家</div></div>
 <div class="stats"><div class="stat"><small>Tổng số hồ sơ</small><b>${db.persons.length}</b><em>${main.length} thuộc dòng họ (${male} nam · ${main.length-male} nữ) · ${related} phối ngẫu/ngoại hệ</em></div><div class="stat"><small>Số thế hệ</small><b>${max} đời</b><em>Từ ${year(person(db.clan.founderId)?.birth)} đến nay</em></div><div class="stat"><small>Chi · Nhánh</small><b>${db.branches.length}</b><em>${db.branches.map(b=>b.code).join(' · ')}</em></div><div class="stat"><small>Kho tư liệu</small><b>${db.media.length}</b><em>ảnh và tài liệu</em></div></div>
 <div class="grid-2"><div class="panel"><div class="panel-head"><h3>Cập nhật gần đây</h3><button class="btn" onclick="showView('members')">Xem tất cả</button></div><div class="activity">${db.persons.slice().sort((a,b)=>String(b.updatedAt||b.createdAt||'').localeCompare(String(a.updatedAt||a.createdAt||''))).slice(0,5).map(p=>`<div class="activity-item">${avatar(p)}<div><b>${esc(p.name)}</b><small>${p.code} · ${branch(p.branchId)?.name||'Chưa xếp chi'}</small></div></div>`).join('')}</div></div>
 <div class="panel"><div class="panel-head"><h3>Thành viên theo đời</h3></div><div class="generation-bars">${counts.map((n,i)=>`<div><i style="height:${Math.max(8,n/Math.max(...counts)*110)}px"></i>Đời ${i+1}<br><b>${n}</b></div>`).join('')}</div></div></div>`;
}
function treeNode(p,depth=0){if(!p||depth>12)return'';const adoptedStop=p.childRelation==='adopted',stop=(db.clan.lineageMode==='patrilineal'&&p.gender==='female')||adoptedStop;const kids=stop?[]:childrenOf(p.id).filter(isMain);const relation=p.childRelation==='adopted_heir'?'<small>Con nuôi kế tự · Được nối dõi</small>':adoptedStop?'<small class="stop">Con nuôi · Không nối dõi</small>':'';return `<li class="${kids.length?'':'leaf'}"><div class="person-card ${p.gender==='female'?'female':''}" onclick="showPerson('${p.id}')">${avatar(p)}<b>${esc(p.name)}</b><small>Đời ${generation(p.id)||'—'}</small>${relation}${!adoptedStop&&stop?'<small class="stop">Xuất giá · Dừng nhánh</small>':''}</div>${kids.length?`<ul>${kids.map(k=>treeNode(k,depth+1)).join('')}</ul>`:''}</li>`}
function renderTree(){const root=person(db.clan.founderId)||db.persons.find(isMain);treeZoomLevel=1;$('#tree').innerHTML=`<div class="toolbar"><select id="treeBranch"><option value="">Toàn dòng họ</option>${db.branches.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select><button class="btn" onclick="window.print()">⤓ In / PDF</button><button class="btn" onclick="startAreaExport()">▦ Chọn vùng & Xuất</button><div class="zoom-controls"><button class="btn small" onclick="treeZoom(-0.1)" title="Thu nhỏ">－</button><span id="zoomLabel">100%</span><button class="btn small" onclick="treeZoom(0.1)" title="Phóng to">＋</button><button class="btn small" onclick="treeZoomReset()" title="Về 100%">Đặt lại</button></div><span class="chip">Nam hệ: Nữ dừng nhánh</span><span class="chip hint">Kéo chuột để di chuyển xem</span></div><div class="tree-wrap">${root?`<div class="tree-zoom-viewport"><ul class="tree-root">${treeNode(root)}</ul></div>`:`<div class="empty"><h3>Gia phả đang trống</h3><p>Hãy thêm Thủy tổ hoặc thành viên đầu tiên để bắt đầu xây dựng cây.</p><button class="btn primary" onclick="openPersonForm()">＋ Thêm thành viên đầu tiên</button></div>`}</div>`;$('#treeBranch').onchange=e=>{const b=branch(e.target.value);const r=b&&person(b.founderId);const tree=$('.tree-root');if(tree)tree.innerHTML=r?treeNode(r):treeNode(root);treeZoomLevel=1;applyTreeZoom()};ensureTreePanHandlers();applyTreeZoom()}
function renderMembers(q=''){const x=q.toLowerCase();const rows=db.persons.filter(p=>!x||[p.name,p.code,p.hometown,p.occupation,branch(p.branchId)?.name].join(' ').toLowerCase().includes(x));$('#members').innerHTML=`<div class="toolbar"><input class="grow" id="memberSearch" placeholder="Tìm trong danh sách..." value="${esc(q)}"><select id="memberBranch"><option value="">Tất cả chi nhánh</option>${db.branches.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select><button class="btn primary" onclick="openPersonForm()">＋ Thêm người</button></div><div class="table-wrap"><table><thead><tr><th>Thành viên</th><th>Đời</th><th>Chi · Nhánh</th><th>Năm sinh</th><th>Vai trò</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr data-branch="${p.branchId}"><td><div class="name-cell">${avatar(p)}<div><b>${esc(p.name)}</b><small>${p.code}</small></div></div></td><td>${generation(p.id)||'—'}</td><td>${esc(branch(p.branchId)?.name||'—')}</td><td>${year(p.birth)}</td><td><span class="chip ${p.gender}">${p.membership==='external'?'Ngoại hệ':p.membership==='spouse'?'Phối ngẫu':p.gender==='female'?'Nữ thành viên dòng họ':'Thành viên Nam hệ'}</span></td><td class="actions"><button onclick="showPerson('${p.id}')">◎</button><button onclick="openPersonForm('${p.id}')">✎</button></td></tr>`).join('')}</tbody></table></div>`;$('#memberSearch').oninput=e=>renderMembers(e.target.value);$('#memberBranch').onchange=e=>$$('tbody tr').forEach(r=>r.hidden=!!e.target.value&&r.dataset.branch!==e.target.value)}
const renderMembersInSavedOrder=renderMembers;renderMembers=function(q=''){renderMembersInSavedOrder('');const tbody=$('#members tbody'),search=$('#memberSearch'),branchSelect=$('#memberBranch');if(!tbody)return;search.placeholder='Chỉ tìm trong Họ và tên thành viên...';search.value=q;const rows=[...tbody.rows].sort((a,b)=>{const codeA=a.querySelector('.name-cell small')?.textContent||'',codeB=b.querySelector('.name-cell small')?.textContent||'',pa=db.persons.find(p=>p.code===codeA),pb=db.persons.find(p=>p.code===codeB);return pa&&pb?personDisplayCompare(pa,pb):0}),apply=()=>{const keyword=normalizeSearch(search.value),branchId=branchSelect.value,matched=rows.filter(row=>{const code=row.querySelector('.name-cell small')?.textContent||'',p=db.persons.find(x=>x.code===code),memberName=normalizeSearch(p?.name);return (!keyword||memberName.includes(keyword))&&(!branchId||p?.branchId===branchId)});tbody.replaceChildren(...matched)};search.oninput=apply;branchSelect.onchange=apply;apply()};
const renderMembersWithDuplicateMerge=renderMembers;renderMembers=function(q=''){renderMembersWithDuplicateMerge(q);const tbody=$('#members tbody');if(!tbody)return;[...tbody.rows].forEach(row=>{const code=row.querySelector('.name-cell small')?.textContent||'',p=db.persons.find(x=>x.code===code),duplicates=p?db.persons.filter(x=>x.id!==p.id&&duplicateSignature(x)===duplicateSignature(p)):[];if(!duplicates.length)return;const actions=row.querySelector('.actions');if(actions&&!actions.querySelector('.merge-duplicate'))actions.insertAdjacentHTML('afterbegin',`<button class="merge-duplicate" title="Hợp nhất hồ sơ trùng" onclick="mergeVerifiedDuplicate('${p.id}')">⇄ Hợp nhất</button>`)})};
const renderMembersWithSafeCancel=renderMembers;renderMembers=function(q=''){renderMembersWithSafeCancel(q);const tbody=$('#members tbody');if(!tbody)return;[...tbody.rows].forEach(row=>{const code=row.querySelector('.name-cell small')?.textContent||'',p=db.persons.find(x=>x.code===code),actions=row.querySelector('.actions');if(p&&actions&&!actions.querySelector('.cancel-extra-profile'))actions.insertAdjacentHTML('beforeend',`<button class="cancel-extra-profile" title="Hủy hồ sơ nhập thừa" onclick="cancelExtraProfile('${p.id}')">🗑 Hủy</button>`)})};
window.cancelExtraProfile=function(id){const p=person(id);if(!p)return;const children=db.persons.filter(x=>x.fatherId===id||x.motherId===id),spouseLinks=db.persons.filter(x=>x.spouseOfId===id),foundedBranches=db.branches.filter(b=>b.founderId===id),familyLinks=(db.families||[]).filter(f=>f.husbandId===id||f.wifeId===id),isFounder=db.clan.founderId===id;if(children.length||spouseLinks.length||foundedBranches.length||familyLinks.length||isFounder){alert(`Không thể hủy ${p.name} (${p.code}) vì hồ sơ đang có liên kết:\n\n• ${children.length} người con\n• ${spouseLinks.length+familyLinks.length} quan hệ phối ngẫu/gia đình\n• ${foundedBranches.length} Chi–Nhánh\n${isFounder?'• Đây là hồ sơ Thủy tổ\n':''}\nHãy dùng Hợp nhất hoặc chuyển các liên kết sang đúng hồ sơ trước.`);return}if(!confirm(`Hủy hồ sơ nhập thừa ${p.name} (${p.code})?\n\nHồ sơ sẽ được đưa vào thùng tạm và có thể khôi phục.`))return;const before=JSON.stringify(db);db.deletedPersons??=[];db.deletedPersons.push({...p,deletedAt:new Date().toISOString()});db.persons=db.persons.filter(x=>x.id!==id);if(!save()){db=JSON.parse(before);return}renderAll();toast('Đã đưa hồ sơ vào thùng tạm')};
