function deduplicateSavedProfiles(){const latestPersons=new Map();db.persons.forEach(p=>latestPersons.set(p.id,p));db.persons=[...latestPersons.values()];const latestBranchByFounder=new Map();db.branches.forEach(b=>{if(b.founderId&&(b.order||b.startGeneration))latestBranchByFounder.set(b.founderId,b)});const replacements=new Map(),keptIds=new Set([...latestBranchByFounder.values()].map(b=>b.id));db.branches.forEach(b=>{const kept=latestBranchByFounder.get(b.founderId);if(kept&&kept.id!==b.id)replacements.set(b.id,kept.id)});if(replacements.size){db.persons.forEach(p=>{if(replacements.has(p.branchId))p.branchId=replacements.get(p.branchId)});db.branches.forEach(b=>{if(replacements.has(b.parentBranchId))b.parentBranchId=replacements.get(b.parentBranchId)});db.branches=db.branches.filter(b=>!replacements.has(b.id)||keptIds.has(b.id))}}
