$('#restoreInput').onchange=async e=>{const f=e.target.files[0];if(!f)return;const text=await f.text();try{if(f.name.toLowerCase().endsWith('.json')){const next=JSON.parse(text);if(!next.persons||!next.clan)throw Error();const clanCount=next.persons.filter(p=>p.membership==='lineage'||p.membership==='clan').length,relatedCount=next.persons.length-clanCount;if(confirm(`Khôi phục tổng cộng ${next.persons.length} hồ sơ?\n\n• ${clanCount} thành viên thuộc dòng họ\n• ${relatedCount} phối ngẫu/ngoại hệ\n\nDữ liệu hiện tại sẽ được thay thế.`)){db=next;save();renderAll();toast('Khôi phục thành công')}}else if(/\.csv$/i.test(f.name))importCSV(text);else importGEDCOM(text)}catch{toast('Tệp không hợp lệ hoặc không đúng định dạng')}e.target.value=''};
