function importGEDCOM(text){const records=text.split(/\n(?=0 @I[^\n]+ INDI)/).slice(1);const added=[];records.forEach((r,i)=>{const name=(r.match(/\n1 NAME (.+)/)?.[1]||'Chưa rõ').replace(/([^/]*)\/([^/]*)\//,'$2 $1').trim();const sex=r.match(/\n1 SEX ([MF])/i)?.[1];const dates=[...r.matchAll(/\n1 (BIRT|DEAT)\n2 DATE (.+)/g)];added.push({id:uid(),code:'GED-'+String(i+1).padStart(4,'0'),name,gender:sex==='F'?'female':'male',birth:dates.find(x=>x[1]==='BIRT')?.[2]||'',death:dates.find(x=>x[1]==='DEAT')?.[2]||'',fatherId:'',motherId:'',branchId:'',membership:sex==='F'?'clan':'lineage',occupation:'',hometown:'',bio:'Nhập từ GEDCOM',avatar:'',createdAt:new Date().toISOString()})});if(!added.length)throw Error();if(confirm(`Nhập thêm ${added.length} cá nhân từ GEDCOM?`)){db.persons.push(...added);save();renderAll();toast('Đã nhập GEDCOM (quan hệ phức tạp cần rà soát)')}}
